'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var IS_BROWSER = require( '@stdlib/assert/is-browser' );
var dlapmr = require( './../lib' );


// VARIABLES //

var opts = {
	'skip': IS_BROWSER
};


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlapmr, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 8', function test( t ) {
	t.strictEqual( dlapmr.length, 8, 'returns expected value' );
	t.end();
});

tape( 'the function has an `ndarray` method', function test( t ) {
	t.strictEqual( typeof dlapmr.ndarray, 'function', 'has method' );
	t.end();
});

tape( 'the `ndarray` method has an arity of 10', function test( t ) {
	t.strictEqual( dlapmr.ndarray.length, 10, 'returns expected value' );
	t.end();
});

tape( 'if a native implementation is available, the main export is the native implementation', opts, function test( t ) {
	var dlapmr = proxyquire( './../lib', {
		'@stdlib/utils/try-require': tryRequire
	});

	t.strictEqual( dlapmr, mock, 'returns expected value' );
	t.end();

	function tryRequire() {
		return mock;
	}

	function mock() {
		// Mock...
	}
});

tape( 'if a native implementation is not available, the main export is a JavaScript implementation', opts, function test( t ) {
	var dlapmr;
	var main;

	main = require( './../lib/main.js' );

	dlapmr = proxyquire( './../lib', {
		'@stdlib/utils/try-require': tryRequire
	});

	t.strictEqual( dlapmr, main, 'returns expected value' );
	t.end();

	function tryRequire() {
		return new Error( 'Cannot find module' );
	}
});
